def bbox_fill(g):
    H,W=len(g),len(g[0])
    bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bgc]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[row[:] for row in g]
    for rr in (r0,r1):
        for cc in range(c0,c1+1):
            if out[rr][cc]==bgc: out[rr][cc]=2
    for cc in (c0,c1):
        for rr in range(r0,r1+1):
            if out[rr][cc]==bgc: out[rr][cc]=2
    return out
